const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const dist = path.dirname(require.resolve('leaflet/dist/leaflet.js'));
const js = fs.readFileSync(path.join(dist, 'leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
const css = fs.readFileSync(path.join(dist, 'leaflet.css'), 'utf8');
fs.writeFileSync(path.join(root, 'src/components/leafletAssets.ts'), '// Generated by scripts/bundle-map-assets.cjs. Leaflet 1.9.4; see assets/licenses/Leaflet.txt.\nexport const leafletJavaScript = ' + JSON.stringify(js) + ';\nexport const leafletCss = ' + JSON.stringify(css) + ';\n');
fs.mkdirSync(path.join(root, 'assets/licenses'), { recursive: true });
fs.copyFileSync(path.join(dist, '../LICENSE'), path.join(root, 'assets/licenses/Leaflet.txt'));
